const $=id=>document.getElementById(id);let stream,recipes=[],lots=[],products={};
let KEY='offmenu-pantry-v1',PRODUCTS='offmenu-products-v1',RECIPES='offmenu-recipes-v1',PROFILE='offmenu-profile-v1',SELECTIONS='offmenu-selections-v1';
let editingId=null,lastReceipt=null,latestAcceptedId=null,torchBusy=false,lastFeedbackAt=0;let statisticsPeriod='daily',editingLocationId=null,editingMemberId=null;let feedback={sound:false,vibration:false,screen:false,light:false,speech:false};
