function msg(text){$('message').textContent=text;}
function draftKey(){return KEY+'-checkout';}
function saveDraft(){if(session)localStorage.setItem(draftKey(),JSON.stringify(session));else localStorage.removeItem(draftKey());}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function save(next){profile.batches=reconcileCookedStock(profile.batches||[],next,{date:today()});localStorage.setItem(PROFILE,JSON.stringify(profile));localStorage.setItem(KEY,JSON.stringify(next));lots=next;markDirty();}
function card(parent,title,details){const a=document.createElement('article'),b=document.createElement('strong'),p=document.createElement('p');b.textContent=title;p.textContent=details;a.append(b,p);parent.append(a);return a;}
function stop(){scanner.stop();}
async function jsonFetch(url){const r=await fetch(url,{signal:AbortSignal.timeout(15000)});const v=await r.json();if(!r.ok)throw Error(v.error||'Lookup unavailable.');return v;}
function suggest(name){const vocabulary=[...new Set(recipes.flatMap(r=>r.ingredients.map(i=>i.ingredient)))].sort((a,b)=>b.length-a.length);const n=normalize(name);return vocabulary.find(i=>n.includes(i))||'';}
async function getProduct(code){const store=products,storageKey=PRODUCTS;let p=store[code];if(p)return p;const data=await jsonFetch('/api/product?barcode='+encodeURIComponent(code));if(data.status!==1||!data.product)throw Error('Product details unavailable.');p={name:data.product.product_name_en||data.product.product_name||code,quantity:data.product.quantity||'',brand:data.product.brands||'',nutriments:data.product.nutriments||{},nutrition_data_per:data.product.nutrition_data_per||'',ingredients:data.product.ingredients_text||'',allergens:data.product.allergens_tags||[],unifiedRecords:data.offmenu?.records||[],product_quantity:data.product.product_quantity,product_quantity_unit:data.product.product_quantity_unit};store[code]=p;localStorage.setItem(storageKey,JSON.stringify(store));if(products===store)markDirty();return p;}
function trustedIngredient(p,code){return p?.ingredient||lots.find(l=>l.barcode===code&&!l.needsReview)?.ingredient;}
function mappedIngredient(p,code){return p?.ingredient||lots.find(l=>l.barcode===code&&!l.needsReview)?.ingredient||suggest(p?.name||'')||'unmapped';}
function autoAccept(code,p=null){if(!session)return;if(session.mode==='waste'){const source=lots.find(l=>l.barcode===code&&(l.location?.area||'Unassigned')===session.area&&(l.location?.shelf||'Unsorted')===session.shelf&&!session.items.some(i=>i.id===l.id));if(!source)return msg('No remaining matching inventory item in this source location. Nothing removed.');session.items.push({...source,pending:false});saveDraft();renderBasket();displayAccepted(source,products[code]);scanFeedback(source.name);return;}try{const current=session;const lot=makeAutoLot(code,p,mappedIngredient(p,code));lot.pending=!p;lot.needsReview=!p?.name||!trustedIngredient(p,code);current.items.push(lot);saveDraft();renderBasket();scanFeedback(p?.name);displayAccepted(lot,p);msg(p?'Accepted. Next item, please.':'Accepted. Looking up details while you keep scanning…');if(!p)void getProduct(code).then(product=>{const index=current.items.findIndex(i=>i.id===lot.id);if(index<0)return;const hydrated={...makeAutoLot(code,product,mappedIngredient(product,code)),id:lot.id,pending:false};hydrated.needsReview=!trustedIngredient(product,code);current.items[index]=hydrated;if(session===current){saveDraft();renderBasket();if(latestAcceptedId===lot.id)displayAccepted(hydrated,product);if(feedback.speech)speakProduct(product.name);if($('finish-dialog').open)renderFinalReceipt(current,false);}}).catch(()=>{const existing=current.items.find(i=>i.id===lot.id);if(existing){existing.pending=false;existing.needsReview=true;if(session===current){saveDraft();renderBasket();if($('finish-dialog').open)renderFinalReceipt(current,false);msg('Unknown product kept on your receipt. Keep scanning; review it at the end.');}}});}catch(e){msg(e.message);}}
async function lookup(){const code=$('barcode').value.trim();if(!/^\d{4,32}$/.test(code))return msg('Enter a barcode with 4–32 digits.');autoAccept(code,products[code]||null);$('barcode').value='';}
function displayAccepted(lot,p){latestAcceptedId=lot.id;$('register-status').textContent=lot.pending?'ACCEPTED · LOOKING UP':'ITEM ACCEPTED ✓';$('register-name').textContent=lot.name;$('register-amount').textContent=lot.amountBasis==='package'?'1 package · details on final receipt':`${lot.quantity} ${lot.unit} · full pack assumed`;$('barcode').value=lot.barcode;$('item-review').hidden=false;$('add').hidden=true;$('skip-item').hidden=true;$('product-heading').textContent=lot.name;$('product-avatar').textContent=foodIcon(lot.name);$('product-brand').textContent=p?.brand||'Accepted automatically';renderNutrition(p||{});$('product-ingredients').textContent=p?.ingredients||'Check the package for ingredients and allergens.';pulseRegister();}
$('lookup').onclick=lookup;
$('barcode').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();void lookup();}});
const scanner=setupScanner({
 canScan:()=>{if(session)return true;msg('Choose a shelf and open your checkout first.');return false;},
 onCode:code=>autoAccept(code,products[code]||null),
 onStream:camera=>{stream=camera;configureLight();},
 onStartGesture:async()=>{if(feedback.sound){try{await enableAudio();}catch{}}}
});

function pantry(){freshness.render();updateMenuLocations();renderLocations();const target=$('inventory');target.replaceChildren();$('pantry-total').textContent=lots.length;const filter=$('shelf-filter').value;const visible=lots.filter(l=>!filter||(l.location?.area||'Unassigned')===filter);if(!visible.length){const empty=document.createElement('div');empty.className='empty-state';empty.innerHTML='<span>▤</span><h3>A little room for possibility.</h3><p>Choose a shelf and scan your first items through checkout.</p>';target.append(empty);}for(const r of visible){const a=document.createElement('article'),location=document.createElement('div'),avatar=document.createElement('span');location.className='location-label';location.textContent=locationKey(r.location).toUpperCase();avatar.className='product-avatar';avatar.textContent=foodIcon(r.name);a.append(location,avatar);const name=document.createElement('strong');name.textContent=r.name;const detail=document.createElement('p');detail.textContent=displayAmount(r.quantity,r.unit,profile.units)+' · '+r.ingredient;a.append(name,detail);if(r.expires){const expiry=document.createElement('p');expiry.textContent=(r.expires<today()?'Past entered expiry · excluded from meals':'Expiry')+' · '+r.expires;a.append(expiry);}const b=document.createElement('button');b.className='outline';b.textContent='Remove item';b.onclick=()=>{try{save(lots.filter(x=>x.id!==r.id));pantry();findMeals();}catch(e){msg('Unable to save: '+e.message);}};a.append(b);target.append(a);}}
function unexpiredInventory(){return lots.filter(l=>!l.expires||l.expires>=today());}
function menuInventory(){const key=$('menu-location').value;return unexpiredInventory().filter(l=>!key||locationKey(l.location)===key);}
function findMeals(){recipeLibrary?.refresh();const target=$('meals');target.replaceChildren();const servings=Number($('servings').value);const inventory=menuInventory();renderDinnerMembers();const diners=(profile.members||[]).filter(m=>!absentDiners.has(m.id));let rows=rankedMenus($('show-review-meals').checked?recipes:recipes.filter(quantified),inventory,products,diners,servings,today());const all=rows;$('recipe-count').textContent=`${recipes.filter(quantified).length} quantified recipes · ${servings} portions · start with three options`;$('menu-overview').replaceChildren();for(const [label,value]of [['Ready to cook',all.filter(r=>r.status==='ready').length],['Menus to explore',recipes.length],['Items in scope',inventory.length]]){const box=document.createElement('span'),b=document.createElement('b');b.textContent=value;box.append(b,document.createTextNode(label));$('menu-overview').append(box);}const search=normalize($('menu-search').value);const status=$('menu-ready').value;rows=rows.filter(r=>(!status||r.status===status)&&(!search||normalize(r.title+' '+r.ingredients.map(i=>i.raw||i.ingredient).join(' ')).includes(search)));if(!rows.length){const empty=document.createElement('div');empty.className='empty-state';empty.textContent='No matching menus yet. Try another ingredient or choose the whole kitchen.';target.append(empty);}for(const r of rows.slice(0,$('show-all-meals').checked||search||status?60:3)){const a=document.createElement('article'),badge=document.createElement('span'),title=document.createElement('strong');badge.className='meal-status'+(r.status==='ready'?'':' missing-status');badge.textContent=r.status==='ready'?'READY TO COOK':r.status==='needs_review'?'REVIEW SOURCE QUANTITIES':'INGREDIENTS TO ADD';title.textContent=r.title;a.append(badge,title);const info=document.createElement('p');info.textContent=`${servings} portions`+(r.time?' · '+r.time:'');a.append(info);const availability=document.createElement('p');availability.textContent=r.status==='ready'?'All measured ingredients are available.':r.missing.length?'Missing: '+r.missing.map(i=>`${i.quantity} ${i.unit} ${i.ingredient}`).join(', '):'Some original quantities need review.';if(r.unknown.length)availability.textContent+=' · '+r.unknown.length+' ingredient quantities need review.';a.append(availability);const family=document.createElement('p');family.className='menu-family-status'+(r.group.compatible?'':' conflict');family.textContent=!diners.length?'Add household members for personalised menus.':r.group.compatible?(r.group.checks.length?'Needs checking for the selected diners':'No known ingredient conflict for the selected diners')+(r.group.changes.length?' · '+r.group.changes.join('; '):''):'Separate meal needed for '+r.group.blocked.join(', ');if(r.group.checks.length)family.textContent+=' · '+[...new Set(r.group.checks)].join('; ');a.append(family);const locations=[...new Set(inventory.filter(l=>r.ingredients.some(i=>normalize(i.ingredient)===normalize(l.ingredient))).map(l=>locationKey(l.location)))];const place=document.createElement('p');place.className='menu-location-note';place.textContent=locations.length?'From '+locations.join(' · '):'Add matching ingredients to your kitchen.';a.append(place);const detail=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Ingredients, quantities & directions';detail.append(summary);const ingredients=document.createElement('ul');ingredients.className='menu-ingredients';for(const ingredient of r.ingredients){const line=document.createElement('li');const amount=ingredient.quantity==null?'Quantity not specified':displayAmount(ingredient.quantity*servings/r.servings,ingredient.unit,profile.units);line.textContent=ingredient.raw&&ingredient.quantity==null?ingredient.raw+' · quantity needs review':`${amount} ${ingredient.ingredient}${ingredient.optional?' (optional)':''}`;const stock=inventory.filter(l=>normalize(l.ingredient)===normalize(ingredient.ingredient)&&!l.needsReview);if(stock.length){const storage=document.createElement('small');storage.textContent=' — '+[...new Set(stock.map(l=>locationKey(l.location)))].join(', ');line.append(storage);}ingredients.append(line);}detail.append(ingredients);const steps=document.createElement('ol');for(const instruction of r.instructions){const step=document.createElement('li');step.textContent=instruction;steps.append(step);}detail.append(steps);if(r.ingredients.some(i=>i.raw)){const original=document.createElement('details'),s=document.createElement('summary'),p=document.createElement('p');s.textContent='Original ingredient wording';p.textContent=r.ingredients.map(i=>i.raw||i.ingredient).join('\n');p.style.whiteSpace='pre-line';original.append(s,p);detail.append(original);}const origin=document.createElement('p');origin.className='recipe-origin';const link=document.createElement('a');link.textContent=r.source;if(/^https?:\/\//.test(r.source))link.href=r.source;origin.append(link,document.createTextNode(' · '+r.license+(r.attribution?' · '+r.attribution:'')));detail.append(origin);a.append(detail);const food=document.createElement('details'),foodSummary=document.createElement('summary'),foodInfo=document.createElement('p');foodSummary.textContent='Food data & estimated nutrition';foodInfo.className='recipe-food-data';const data=planSummary([{recipeId:r.id,date:today(),servings}],recipes,inventory,products,[today()]);foodInfo.textContent=NUTRIENTS.map(([key,label,unit])=>{const n=data.totals[key];return `${label}: ${n.known?Number(n.value.toPrecision(3))+' '+unit:'not available'}${n.known&&n.known<n.total?' (partial)':''}`;}).join('\n')+'\nFor all '+servings+' portions. Based on the first matching mapped product for each ingredient; brands can differ. Missing data is excluded.';foodInfo.style.whiteSpace='pre-line';food.append(foodSummary,foodInfo);a.append(food);const add=document.createElement('button');add.className='coral';add.textContent='Add to '+new Date($('plan-date').value+'T12:00:00').toLocaleDateString(undefined,{weekday:'short'} )+' menu +';add.onclick=()=>{profile.plan||=[];profile.plan.push({id:crypto.randomUUID(),recipeId:r.id,date:$('plan-date').value,slot:$('plan-slot').value,servings,memberIds:(profile.members||[]).map(m=>m.id),adjustments:r.group.changes});localStorage.setItem(PROFILE,JSON.stringify(profile));markDirty();renderPlan();$('menu-notice').textContent=r.title+' added to '+$('plan-date').value+' '+$('plan-slot').value.toLowerCase()+'.';};a.append(add);if(quantified(r)){const cook=document.createElement('button');cook.textContent='Cook this meal';cook.className='outline';cook.disabled=!r.group.compatible;cook.onclick=()=>journey.openCook(r);a.append(cook);}const select=document.createElement('button');select.className='outline';select.textContent=selections.includes(r.id)?'Saved favourite ✓':'Save as favourite';select.onclick=()=>{selections=selections.includes(r.id)?selections.filter(x=>x!==r.id):[...selections,r.id];localStorage.setItem(SELECTIONS,JSON.stringify(selections));markDirty();findMeals();};a.append(select);target.append(a);}renderPlan();}
$('refresh').onclick=()=>{try{findMeals();}catch(e){msg(e.message);}};
$('add').onsubmit=e=>{e.preventDefault();try{const target=session||lastReceipt;if(!target||!editingId)throw Error('Choose an item to correct on the final receipt.');const index=target.items.findIndex(i=>i.id===editingId);if(index<0)throw Error('Item no longer on receipt.');const old=target.items[index],item={...old};for(const key of ['name','ingredient','quantity','unit','expires'])item[key]=$(key).value;item.amountBasis='manual';item.needsReview=item.ingredient==='unmapped';const edited=validateLot(item);target.items[index]=edited;if(session){saveDraft();renderBasket();}else{save(lots.map(i=>i.id===edited.id?{...i,...edited}:i));saveReceipt(lastReceipt);pantry();findMeals();}editingId=null;$('item-review').hidden=true;if(!session){$('checkout-run').hidden=true;$('checkout-complete').hidden=false;}renderFinalReceipt(target,!session);$('finish-dialog').showModal();}catch(e){msg(e.message);}};
$('shops').onclick=async()=>{const target=$('prices');target.replaceChildren();target.textContent='Checking dated observations…';try{const code=$('barcode').value.trim();if(!/^\d{4,32}$/.test(code))throw Error('Enter or scan a barcode first.');const v=await jsonFetch('/api/prices?barcode='+encodeURIComponent(code));target.replaceChildren();const observations=v.items||v.results||[];const rows=profile.country?observations.filter(r=>(r.location?.osm_address_country_code||'').toUpperCase()===profile.country):observations;if(!rows.length)target.textContent='No matching observations in the latest sample'+(profile.country?' for '+names.of(profile.country):'')+'. This does not mean no retailer sells it.';for(const r of rows)card(target,r.location?.osm_name||r.location?.osm_display_name||'Shop observation #'+r.location_id,`${r.currency} ${r.price} · ${r.date} · ${r.location?.osm_address_country||'country unknown'} · historical observation`);if(v.offmenu_stale)card(target,'Cached observations','Refresh unavailable; these are earlier downloaded observations.');}catch(e){target.textContent=e.message;}};
function download(filename,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').onclick=()=>download('offmenu-pantry.json',{version:1,inventory:lots,profile,products,recipes,selections});
async function readJSON(input){const f=input.files[0];if(!f)return null;if(f.size>2_000_000)throw Error('File must be under 2 MB.');return JSON.parse(await f.text());}
$('restore').onchange=async()=>{try{const v=await readJSON($('restore'));if(!v)return;if(v.version!==1||!Array.isArray(v.inventory)||v.inventory.length>10000)throw Error('Invalid pantry backup.');const next=v.inventory.map(validateLot);if(new Set(next.map(x=>x.id)).size!==next.length)throw Error('Backup has duplicate item IDs.');if(lots.length&&!confirm('Replace your pantry with this backup?'))return;const state=v.profile?validateState({...v,inventory:next}):null;save(next);if(state){profile=state.profile;products=state.products;recipes=state.recipes;selections=state.selections;for(const [key,val]of [[PROFILE,profile],[PRODUCTS,products],[RECIPES,recipes],[SELECTIONS,selections]])localStorage.setItem(key,JSON.stringify(val));loadProfile();}pantry();findMeals();msg('Backup restored in this browser. Save to cloud to back it up.');}catch(e){msg(e.message);}finally{$('restore').value='';}};
$('recipe-import').onchange=async()=>{try{const v=await readJSON($('recipe-import'));if(!v)return;const imported=validateRecipes(v);const next=[...new Map([...recipes,...imported].map(r=>[r.id,r])).values()];localStorage.setItem(RECIPES,JSON.stringify(next));recipes=next;markDirty();findMeals();msg('Recipes imported.');}catch(e){msg(e.message);}finally{$('recipe-import').value='';}};
function connectivity(){$('connection').textContent=demoMode?'Demo kitchen · separate sample data.':navigator.onLine?(user?'Signed in · automatic cloud saves; local copy available offline.':'Guest pantry · saved in this browser.'):'Offline · Pantry and downloaded recipes work. New product and shop lookups need internet.';}window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);
async function init(){try{await initAuth();loadProfile();lots=JSON.parse(localStorage.getItem(KEY)||'[]').map(validateLot);products=JSON.parse(localStorage.getItem(PRODUCTS)||'{}');const stored=localStorage.getItem(RECIPES);const fresh=await fetchRecipes();recipes=validateRecipes([...new Map([...(stored?JSON.parse(stored):[]),...fresh].map(r=>[r.id,r])).values()]);localStorage.setItem(RECIPES,JSON.stringify(recipes));pantry();findMeals();connectivity();if('serviceWorker'in navigator)await navigator.serviceWorker.register('/sw.js');}catch(e){msg('Setup needs attention: '+e.message);}}
function markDirty(){dirty=true;if(typeof syncReady!=='undefined'&&syncReady){if(sharing.active())sharing.schedule();else autoSync.schedule();}if(user&&!demoMode)localStorage.setItem(KEY+'-dirty','1');$('sync-status').textContent=demoMode?'Demo changes stay separate from your kitchen.':user?'Local changes · saving automatically.':'Guest data is saved in this browser.';}
function loadProfile(){profile=JSON.parse(localStorage.getItem(PROFILE)||'{"country":"","units":"metric","servings":2}');selections=JSON.parse(localStorage.getItem(SELECTIONS)||'[]');for(const link of document.querySelectorAll('a[href^="/data-workspace.html"]'))link.href='/data-workspace.html'+(profile.country?'?country='+encodeURIComponent(profile.country):'');$('country').value=profile.country||'';if(syncReady)journey.applyPreferences();$('units').value=profile.units||'metric';$('servings').value=profile.servings||2;lastReceipt=profile.lastReceipt||null;$('view-last-receipt').hidden=!lastReceipt;feedback={sound:false,vibration:false,screen:false,light:false,speech:false,...profile.feedback};applyFeedbackSettings();}
function saveProfile(){profile={...profile,country:$('country').value,units:$('units').value,servings:Number($('servings').value)};localStorage.setItem(PROFILE,JSON.stringify(profile));markDirty();}
for(const id of ['country','units','servings'])$(id).addEventListener('change',saveProfile);
const names=new Intl.DisplayNames(['en'],{type:'region'});const countries='AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW'.split(' ').map(code=>({code,name:names.of(code)}));for(const {code,name}of countries.sort((a,b)=>a.name.localeCompare(b.name))){const option=document.createElement('option');option.value=code;option.textContent=name;$('country').append(option);}
async function fetchRecipes(){const base=await jsonFetch('/recipes.json?v=functional-1');try{const r=await jsonFetch('/api/recipes');return [...new Map([...base,...r].map(x=>[x.id,x])).values()];}catch{return base;}}
function switchAccount(next){user=next;dataUi.reset();const suffix=demoMode?'-demo':next?'-user-'+next.id:'';KEY='offmenu-pantry-v1'+suffix;PRODUCTS='offmenu-products-v1'+suffix;RECIPES='offmenu-recipes-v1'+suffix;PROFILE='offmenu-profile-v1'+suffix;SELECTIONS='offmenu-selections-v1'+suffix;revision=Number(localStorage.getItem(KEY+'-revision')||0);dirty=localStorage.getItem(KEY+'-dirty')==='1';for(const id of ['logout','cloud-save','cloud-load'])$(id).hidden=!next||demoMode;$('auth-controls').hidden=!!next&&!recoveryMode; if(recoveryMode)$('new-password').hidden=false;$('account-status').textContent=next?'Signed in as '+(next.email||next.name||'member'):'Sign in to restore your pantry on another device.';}
async function initAuth(){try{const callback=await handleAuthCallback();if(callback?.type==='invite'){inviteToken=callback.token;$('new-password').hidden=false;}if(callback?.type==='recovery'){recoveryMode=true;$('new-password').hidden=false;}const settings=await getSettings();$('auth-controls').hidden=false;$('signup').hidden=settings.disableSignup;for(const [provider,enabled]of Object.entries(settings.providers)){if(enabled&&provider!=='email'){const b=document.createElement('button');b.className='provider-button';b.innerHTML=providerMark(provider);const label=document.createElement('span');label.textContent='Continue with '+provider[0].toUpperCase()+provider.slice(1);b.append(label);b.onclick=()=>oauthLogin(provider);$('providers').append(b);}}switchAccount(await getUser());}catch{$('auth-controls').hidden=true;$('account-status').textContent='Account setup pending. Guest pantry and offline recipes remain available.';}}
async function cloudRequest(method,body){if(demoMode)throw Error('Exit the demo to save your own kitchen.');await refreshSession();const response=await fetch('/api/state',{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Cloud operation failed.');return data;}
async function loadCloud(ask=true){const data=await cloudRequest('GET');if(data.state){if(ask&&!confirm('Replace this browser copy with the cloud save? Export local changes first.'))return;const state=data.state;localStorage.setItem(KEY,JSON.stringify(state.inventory));localStorage.setItem(PRODUCTS,JSON.stringify(state.products));localStorage.setItem(RECIPES,JSON.stringify(state.recipes));localStorage.setItem(PROFILE,JSON.stringify(state.profile));localStorage.setItem(SELECTIONS,JSON.stringify(state.selections));lots=state.inventory;products=state.products;recipes=validateRecipes([...new Map([...state.recipes,...await fetchRecipes()].map(r=>[r.id,r])).values()]);localStorage.setItem(RECIPES,JSON.stringify(recipes));loadProfile();pantry();findMeals();}revision=data.revision;localStorage.setItem(KEY+'-revision',String(revision));dirty=false;localStorage.removeItem(KEY+'-dirty');if(syncReady&&data.state)autoSync.reset(data.state,data.revision);$('sync-status').textContent=data.state?'Cloud copy restored.':'No cloud copy yet. Add items or import a backup, then save.';}
$('cloud-load').onclick=()=>{if(sharing.active())return syncStatus('Return to your private kitchen before restoring its cloud copy.','pending');return loadCloud().catch(e=>$('sync-status').textContent=e.message);};
$('cloud-save').onclick=async()=>{if(sharing.active()){sharing.schedule();return;}try{saveProfile();const data=await cloudRequest('PUT',{revision,state:{inventory:lots,products,recipes,profile,selections}});revision=data.revision;localStorage.setItem(KEY+'-revision',String(revision));localStorage.removeItem(KEY+'-dirty');dirty=false;$('sync-status').textContent='Saved to cloud. Automatic saving continues.';}catch(e){$('sync-status').textContent=e.message;}};
async function signedIn(next){demoMode=false;session=null;switchAccount(next);sharing.reset();loadProfile();lots=JSON.parse(localStorage.getItem(KEY)||'[]').map(validateLot);products=JSON.parse(localStorage.getItem(PRODUCTS)||'{}');recipes=validateRecipes(JSON.parse(localStorage.getItem(RECIPES)||'null')||await fetchRecipes());pantry();findMeals();connectivity();if(next&&!dirty&&!demoMode&&!localStorage.getItem(KEY+'-shared-session'))await loadCloud(false);else if(next) $('sync-status').textContent='Unsaved local changes retained. Export or save before loading cloud data.';$('password').value='';$('account-dialog').close();if(next){await sharing.resume().catch(e=>syncStatus(e.message,'pending'));autoSync.schedule();openWorkspace();await access.checkConsent();}}
$('login').onclick=async()=>{try{await signedIn(await login($('email').value,$('password').value));}catch(e){$('account-status').textContent=e.message;}};
$('signup').onclick=async()=>{try{await signup($('email').value,$('password').value);const next=await getUser();if(next)await signedIn(next);else $('account-status').textContent='Check your email to confirm your account.';$('password').value='';}catch(e){$('account-status').textContent=e.message;}};
$('recover').onclick=async()=>{try{await requestPasswordRecovery($('email').value);$('account-status').textContent='Check your email for recovery instructions.';}catch(e){$('account-status').textContent=e.message;}};
$('new-password').onclick=async()=>{try{const next=inviteToken?await acceptInvite(inviteToken,$('password').value):await updateUser({password:$('password').value});inviteToken=null;recoveryMode=false;$('new-password').hidden=true;await signedIn(next);}catch(e){$('account-status').textContent=e.message;}};
$('logout').onclick=async()=>{try{await logout();await signedIn(null);}catch(e){$('account-status').textContent=e.message;}};


