function foodIcon(name){const n=normalize(name);return /milk|yoghurt|cream/.test(n)?'🥛':/rice|pasta|grain|flour/.test(n)?'🌾':/water|drink|juice/.test(n)?'💧':/egg/.test(n)?'🥚':/apple|fruit|banana/.test(n)?'🍎':/bread/.test(n)?'🍞':/broccoli|vegetable|spinach/.test(n)?'🥬':/fish|salmon/.test(n)?'🐟':'🥫';}
function providerMark(provider){if(provider==='google')return '<span class="provider-logo" aria-hidden="true"><svg viewBox="0 0 48 48"><path fill="#4285F4" d="M43.6 24.5c0-1.5-.1-3-.4-4.4H24v8.4h11a9.4 9.4 0 0 1-4.1 6.2v5.2h6.6c3.8-3.5 6.1-8.7 6.1-15.4Z"/><path fill="#34A853" d="M24 44c5.4 0 9.9-1.8 13.2-4.8l-6.6-5.2c-1.8 1.2-4 1.9-6.6 1.9-5.2 0-9.6-3.5-11.2-8.2H6v5.4A20 20 0 0 0 24 44Z"/><path fill="#FBBC05" d="M12.8 27.7a12 12 0 0 1 0-7.4v-5.4H6a20 20 0 0 0 0 18.2l6.8-5.4Z"/><path fill="#EA4335" d="M24 12.1c2.9 0 5.5 1 7.5 2.9l5.6-5.6A19 19 0 0 0 24 4 20 20 0 0 0 6 14.9l6.8 5.4c1.6-4.7 6-8.2 11.2-8.2Z"/></svg></span>';return '<span class="provider-logo" aria-hidden="true">'+({github:'◉',gitlab:'◆',bitbucket:'▣',facebook:'f'}[provider]||'↗')+'</span>';}
async function openAccount(){await startup;if(!$('account-dialog').open)$('account-dialog').showModal();$('login-heading').textContent=user&&!demoMode?'Your kitchen, connected.':'Come on in.';}
function setView(view){stop();for(const name of ['checkout','shelves','meals','plan','household','insights','integrations','me'])$(name+'-page').hidden=name!==view;for(const tab of document.querySelectorAll('[data-view]')){tab.classList.toggle('active',tab.dataset.view===view);tab.setAttribute('aria-current',tab.dataset.view===view?'page':'false');}if(view==='shelves'){pantry();journey.renderBatches();}if(view==='me'){journey.applyPreferences();void sharing.render();}if(view==='meals')findMeals();if(view==='plan')renderPlan();if(view==='household')renderHousehold();if(view==='insights'||view==='integrations')insights.render();if(view==='integrations'){void access.render();void dataUi.render();}}
function openWorkspace(){stop();$('landing').hidden=true;$('workspace').hidden=false;$('open-pantry').hidden=false;$('workspace-title').textContent=demoMode?'Welcome to your demo kitchen.':'What’s cooking in your kitchen?';$('workspace-kind').textContent=demoMode?'EXPLORE YOUR DEMO MENUS':'YOUR MENUS. YOUR KITCHEN. YOUR WEEK.';$('demo-badge').hidden=!demoMode;$('exit-demo').hidden=!demoMode;$('demo-scan').hidden=!demoMode;$('scan').hidden=demoMode;$('header-login').textContent=user&&!demoMode?'My account':'Log in';setView('meals');try{session=JSON.parse(localStorage.getItem(draftKey())||'null');if(session&&['shelf','shopping','waste'].includes(session.mode)&&Array.isArray(session.items)){session.items=session.items.map(i=>({...validateLot(i),pending:false}));selectedMode=session.mode;selectedArea=session.area;$('shelf-name').value=session.shelf;showRun();}else session=null;}catch{session=null;}window.scrollTo({top:0,behavior:'instant'});}
function setMode(mode){selectedMode=mode;for(const name of ['shelf','shopping','waste']){$('mode-'+name).classList.toggle('selected',name===mode);$('mode-'+name).setAttribute('aria-pressed',String(name===mode));}$('setup-help').textContent=mode==='waste'?'Choose the source location. Scan items you are discarding; review the removal receipt before the inventory changes.':mode==='shelf'?'Clear this shelf onto your bench. Its current inventory stays intact until you review and finish.':'Choose where these groceries will go. Scan one destination at a time, then add them to the items already there.';}
function setArea(area){selectedArea=area;$('storage-area').value=area;for(const b of document.querySelectorAll('[data-area]')){b.classList.toggle('selected',b.dataset.area===area);b.setAttribute('aria-pressed',String(b.dataset.area===area));}}
function startCheckout(){selectedArea=$('storage-area').value.trim();if(!selectedArea){$('storage-area').focus();return;}if(feedback.sound)void enableAudio().catch(()=>{});const shelf=$('shelf-name').value.trim();if(!shelf){$('shelf-name').focus();return;}if(session&&session.items.length&&(session.area!==selectedArea||session.shelf!==shelf||session.mode!==selectedMode)){if(!confirm('Discard the staged items in your paused checkout and start a different shelf? Your saved kitchen is unchanged.'))return;}if(!session||session.area!==selectedArea||session.shelf!==shelf||session.mode!==selectedMode)session={mode:selectedMode,area:selectedArea,shelf,items:[],startedAt:new Date().toISOString()};profile.locations||=DEFAULT_LOCATIONS.map(l=>({...l}));if(!profile.locations.some(l=>l.area===selectedArea&&l.shelf===shelf)){profile.locations.push({id:crypto.randomUUID(),area:selectedArea,shelf});persistProfile();}saveDraft();showRun();beep('open');}
function showRun(){setMode(session.mode);setArea(session.area);$('shelf-name').value=session.shelf;$('checkout-setup').hidden=true;$('checkout-complete').hidden=true;$('checkout-run').hidden=false;$('run-mode').textContent=session.mode==='waste'?'GARBAGE · SOURCE LOCATION':session.mode==='shelf'?'SHELF RESET':'GROCERY UNPACKING';$('run-location').textContent=locationKey({area:session.area,shelf:session.shelf});$('receipt-location').textContent=$('run-location').textContent;$('run-guidance').textContent=session.mode==='waste'?'Scan recorded items from this location. Each scan stages removal of that whole recorded item.':session.mode==='shelf'?'Scan → beep → put it back. Every scan is accepted automatically.':'From your shopping bag to its new home.';$('item-review').hidden=true;$('register-status').textContent='CHECKOUT OPEN';$('register-name').textContent='Next item, please.';$('register-amount').textContent='Your bench → your shelf';renderBasket();}
function renderBasket(){const target=$('basket');target.replaceChildren();const items=session?.items||[];$('register-count').textContent=items.length;$('basket-count').textContent=String(items.length).padStart(2,'0');const pending=items.some(i=>i.pending);$('finish-checkout').disabled=!items.length;$('finish-checkout').textContent='Final receipt →';$('void-last').disabled=!items.length;if(!items.length){const p=document.createElement('p');p.className='receipt-empty';p.textContent='Nothing scanned yet. Let’s see what’s hiding.';target.append(p);}items.forEach((item,index)=>{const row=document.createElement('div');row.className='basket-row';const content=document.createElement('div'),name=document.createElement('strong'),amount=document.createElement('small'),remove=document.createElement('button');name.textContent=item.name;amount.textContent=session?.mode==='waste'?`${item.discardQuantity??item.quantity} ${item.unit} discarded`:item.amountBasis==='package'?'1 package':`${item.quantity} ${item.unit}`;content.append(name,amount);if(item.needsReview||item.pending){const note=document.createElement('small');note.className='item-review-note';note.textContent=item.pending?'Looking up…':'Review details at the end';content.append(note);}remove.textContent='×';remove.setAttribute('aria-label','Void '+item.name+' from checkout');remove.onclick=()=>{session.items.splice(index,1);saveDraft();renderBasket();};row.append(content,remove);target.append(row);});}
function showProduct(product,code){$('add').reset();currentProduct=product;$('barcode').value=code;$('item-review').hidden=false;$('product-heading').textContent=product.name||'Your mystery item';$('product-avatar').textContent=foodIcon(product.name||'');$('product-brand').textContent=product.brand||product.quantity||'Confirm the details below';$('name').value=product.name||'';$('ingredient').value=product.ingredient||lots.find(l=>l.barcode===code)?.ingredient||suggest(product.name||'');const quantity=Number(product.product_quantity);let unit=product.product_quantity_unit;let amount=quantity;if(unit==='kg'){unit='g';amount*=1000;}if(unit==='l'){unit='ml';amount*=1000;}if(['g','ml'].includes(unit)&&Number.isFinite(amount)&&amount>0){$('quantity').value=amount;$('unit').value=unit;}else{const m=(product.quantity||'').match(/^\s*([\d.]+)\s*(g|kg|ml|l)\s*$/i);if(m){amount=Number(m[1]);unit=m[2].toLowerCase();if(unit==='kg'){amount*=1000;unit='g';}if(unit==='l'){amount*=1000;unit='ml';}$('quantity').value=amount;$('unit').value=unit;}else{$('quantity').value='';$('unit').value='g';}}renderNutrition(product);$('product-ingredients').textContent=(product.ingredients||'Ingredients are not available. Check the package.')+(product.allergens?.length?'\nReported allergens: '+product.allergens.join(', '):'\nAlways check the package for allergens.');$('register-status').textContent='FOUND ON THE BELT';$('register-name').textContent=product.name||'Mystery item';$('register-amount').textContent=product.quantity||'Confirm quantity below';pulseRegister();if(window.matchMedia('(max-width:620px)').matches)$('item-review').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});}
function renderNutrition(product){const target=$('nutrition');target.replaceChildren();const rows=nutritionRows(product);if(!rows.some(r=>r.value!==null)){const p=document.createElement('p');p.textContent='No nutrition data for this item yet. Check the package.';target.append(p);return;}const title=document.createElement('div');title.className='nutrition-title';title.textContent=demoMode?'DEMO NUTRITION · ILLUSTRATIVE / 100 G OR ML':'NUTRITION / 100 G OR 100 ML · AS LABELLED';const grid=document.createElement('div');grid.className='nutrition-grid';for(const row of rows){const cell=document.createElement('div'),value=document.createElement('strong'),label=document.createElement('small');cell.className='nutrition-cell';value.textContent=row.value===null?'—':`${row.value} ${row.unit}`;label.textContent=row.label;cell.append(value,label);grid.append(cell);}target.append(title,grid);}
function pulseRegister(){if(!feedback.screen)return;const register=document.querySelector('.register');register.classList.remove('pulse');requestAnimationFrame(()=>register.classList.add('pulse'));}
async function enableAudio(){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return false;audio||=new Audio();await audio.resume();return true;}
function beep(kind='scan'){if(!soundEnabled||!audio)return;try{const now=audio.currentTime;const tones=kind==='finish'?[660,880,1100]:kind==='open'?[440,660]:[1180];tones.forEach((frequency,i)=>{const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(0,now+i*.12);gain.gain.linearRampToValueAtTime(.07,now+i*.12+.01);gain.gain.exponentialRampToValueAtTime(.001,now+i*.12+.1);oscillator.connect(gain);gain.connect(audio.destination);oscillator.start(now+i*.12);oscillator.stop(now+i*.12+.11);});}catch{}}
async function enterDemo(mode='shelf'){await startup;stop();demoMode=true;switchAccount(user);loadProfile();lots=JSON.parse(localStorage.getItem(KEY)||'[]').map(validateLot);products=JSON.parse(localStorage.getItem(PRODUCTS)||'{}');if(!lots.length){const seed=[['Rice','rice',500,'g'],['Eggs','egg',6,'count'],['Peas','peas',500,'g'],['Carrots','carrot',500,'g'],['Olive oil','olive oil',250,'ml'],['Tap water · demo staple','water',20000,'ml']];lots=seed.map(([name,ingredient,quantity,unit],i)=>validateLot({id:'demo-food-'+i,barcode:String(9000000000000+i),name:name+' (demo)',ingredient,quantity,unit,location:{area:'Pantry',shelf:'Shelf 1'},needsReview:false}));localStorage.setItem(KEY,JSON.stringify(lots));}recipes=validateRecipes(await jsonFetch('/recipes.json?v=functional-1'));localStorage.setItem(RECIPES,JSON.stringify(recipes));demoIndex=0;selectedMode=mode;openWorkspace();setMode(mode);setArea('Pantry');pantry();findMeals();connectivity();}
function applyFeedbackSettings(){for(const key of ['sound','vibration','screen','light','speech'])$('feedback-'+key).checked=feedback[key];soundEnabled=feedback.sound;$('sound-toggle').setAttribute('aria-pressed',String(soundEnabled));$('sound-toggle').textContent=soundEnabled?'♪ Sound on':'♪ Sound off';$('feedback-vibration').disabled=typeof navigator.vibrate!=='function';$('vibration-support').textContent=typeof navigator.vibrate==='function'?'A short pulse after each scan.':'Vibration is unavailable in this browser.';$('feedback-speech').disabled=!('speechSynthesis' in window);$('speech-support').textContent='speechSynthesis' in window?'Hear the product name as it is identified.':'Speech is unavailable in this browser.';configureLight();}
function saveFeedback(){profile={...profile,feedback:{...feedback}};localStorage.setItem(PROFILE,JSON.stringify(profile));markDirty();applyFeedbackSettings();}
function configureLight(){const track=stream?.getVideoTracks()[0];let capable=false;try{capable=!!track?.getCapabilities?.().torch;}catch{}$('feedback-light').disabled=!capable;$('light-support').textContent=!track?'Start the camera to check light support.':capable?'A brief pulse from this camera’s light.':'This camera does not offer a controllable light.';}
async function flashLight(){const track=stream?.getVideoTracks()[0];if(torchBusy||!track?.getCapabilities?.().torch)return;torchBusy=true;const original=!!track.getSettings?.().torch;try{await track.applyConstraints({advanced:[{torch:true}]});await new Promise(resolve=>setTimeout(resolve,100));}finally{try{if(track.readyState==='live')await track.applyConstraints({advanced:[{torch:original}]});}catch{}torchBusy=false;}}
function speakProduct(name){if(!feedback.speech||!name||!('speechSynthesis' in window))return;try{const speech=new SpeechSynthesisUtterance(name);speech.lang=navigator.language||'en-AU';speech.rate=1.05;const localVoice=window.speechSynthesis.getVoices().find(v=>v.localService&&v.lang.startsWith(speech.lang.split('-')[0]));if(localVoice)speech.voice=localVoice;window.speechSynthesis.speak(speech);}catch{}}
function scanFeedback(name){beep('scan');if(feedback.vibration&&typeof navigator.vibrate==='function')navigator.vibrate(100);const now=Date.now();if(now-lastFeedbackAt>700){lastFeedbackAt=now;if(feedback.screen){const register=document.querySelector('.register');register.classList.add('scan-glow');setTimeout(()=>register.classList.remove('scan-glow'),200);}if(feedback.light)void flashLight().catch(()=>$('light-support').textContent='Light feedback is unavailable on this device.');}if(feedback.speech)speakProduct(name);}
$('feedback-open').onclick=()=>{applyFeedbackSettings();$('feedback-dialog').showModal();};
for(const key of ['sound','vibration','screen','light','speech'])$('feedback-'+key).onchange=async()=>{feedback[key]=$('feedback-'+key).checked;if(key==='sound'&&feedback.sound){try{if(!await enableAudio())feedback.sound=false;}catch{feedback.sound=false;}}if(key==='speech'&&!feedback.speech&&'speechSynthesis' in window)window.speechSynthesis.cancel();saveFeedback();};
$('feedback-test').onclick=async()=>{if(feedback.sound)await enableAudio();scanFeedback('Coconut milk');};
$('sound-toggle').onclick=async()=>{try{feedback.sound=!feedback.sound;if(feedback.sound&&!await enableAudio())feedback.sound=false;saveFeedback();if(feedback.sound)beep('open');}catch{feedback.sound=false;saveFeedback();}};
for(const id of ['header-login','workspace-account','me-account'])$(id).onclick=openAccount;
$('continue-guest').onclick=async()=>{await startup;$('account-dialog').close();openWorkspace();};$('open-pantry').onclick=async()=>{await startup;openWorkspace();};
$('hero-demo').onclick=()=>enterDemo().catch(e=>msg(e.message));$('delivery-demo').onclick=()=>enterDemo('shopping').catch(e=>msg(e.message));
$('exit-demo').onclick=()=>{demoMode=false;switchAccount(user);location.reload();};
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>setView(b.dataset.view);
for(const b of document.querySelectorAll('[data-area]'))b.onclick=()=>setArea(b.dataset.area);
$('mode-shelf').onclick=()=>setMode('shelf');$('mode-shopping').onclick=()=>setMode('shopping');$('mode-waste').onclick=()=>setMode('waste');$('start-checkout').onclick=startCheckout;
$('change-shelf').onclick=()=>{stop();$('checkout-run').hidden=true;$('checkout-setup').hidden=false;$('start-checkout').textContent=session?.items.length?'Resume or start checkout ↗':'Open my checkout ↗';};
$('demo-scan').onclick=()=>{const p=demoProducts[demoIndex++%demoProducts.length];products[p.barcode]=p;localStorage.setItem(PRODUCTS,JSON.stringify(products));autoAccept(p.barcode,p);};
$('skip-item').onclick=()=>{editingId=null;$('item-review').hidden=true;if(!session){$('checkout-run').hidden=true;$('checkout-complete').hidden=false;}renderFinalReceipt(session||lastReceipt,!session);$('finish-dialog').showModal();};
$('void-last').onclick=()=>{if(!session?.items.length)return;const removed=session.items.pop();saveDraft();renderBasket();$('register-status').textContent='LAST ITEM VOIDED';$('register-name').textContent=removed.name;$('register-amount').textContent='Removed from this checkout';$('item-review').hidden=true;msg('Voided. Keep scanning.');};
$('finish-checkout').onclick=()=>{if(!session?.items.length)return;stop();renderFinalReceipt(session,false);$('finish-dialog').showModal();};
$('confirm-finish').onclick=()=>{try{if(session?.mode==='waste')for(const input of document.querySelectorAll('#finish-items input[data-waste-id]')){const item=session.items.find(i=>i.id===input.dataset.wasteId);if(item)item.discardQuantity=Number(input.value);}const finished={...session,items:session.items.map(i=>({...i,pending:false})),finishedAt:new Date().toISOString()};const updated=finishInventory(lots,finished);save(updated);saveReceipt(finished);if(finished.mode==='waste'){profile.waste||=[];profile.waste.push(finished);persistProfile();}$('finish-dialog').close();const count=finished.items.length;const place=`${finished.area} / ${finished.shelf}`;session=null;saveDraft();$('checkout-run').hidden=true;$('checkout-complete').hidden=false;$('complete-title').textContent=finished.mode==='waste'?'Cleanup, recorded.':finished.mode==='shelf'?'Shelf, sorted.':'Shopping, settled.';$('complete-detail').textContent=`${count} items ${finished.mode==='waste'?'discarded from':'put away in'} ${place}. ${demoMode?'This is your practice kitchen.':user?'Saved on this device. Back it up from your profile.':'Saved in this browser.'}`;beep('finish');pantry();findMeals();}catch(e){$('finish-explanation').textContent=e.message;}};
function saveReceipt(receipt){lastReceipt=receipt;profile={...profile,lastReceipt:receipt};localStorage.setItem(PROFILE,JSON.stringify(profile));markDirty();$('view-last-receipt').hidden=false;}
function renderFinalReceipt(receipt,completed){$('final-receipt-location').textContent=locationKey({area:receipt.area,shelf:receipt.shelf});$('final-receipt-time').textContent=new Date(receipt.finishedAt||receipt.startedAt).toLocaleString();$('finish-summary').textContent=receipt.mode==='waste'?'GARBAGE · SOURCE LOCATION':'SHELF / GROCERY RECEIPT';$('final-receipt-count').textContent=String(receipt.items.length).padStart(2,'0');$('receipt-confirmation').textContent=receipt.mode==='waste'?(completed?'CONFIRMED · REMOVED FROM INVENTORY.':'REVIEW · WHOLE RECORDED ITEMS TO DISCARD.'):completed?'CONFIRMED · GOOD FOOD, ALREADY YOURS.':'REVIEW · FULL PACKS ASSUMED UNLESS EDITED.';$('finish-items').replaceChildren();for(const item of receipt.items){const row=document.createElement('div');row.className='finish-line';const name=document.createElement('span'),amount=document.createElement('strong');name.className='receipt-item-name';name.textContent=item.name;amount.textContent=receipt.mode==='waste'?`${item.discardQuantity??item.quantity} ${item.unit} discarded`:item.amountBasis==='package'?'1 package':`${item.quantity} ${item.unit}`;row.append(name,amount);if(receipt.mode==='waste'&&!completed){const label=document.createElement('label'),input=document.createElement('input');label.textContent='Amount to discard ('+item.unit+')';input.type='number';input.dataset.wasteId=item.id;input.min='0.001';input.max=item.quantity;input.step='any';input.value=item.discardQuantity??item.quantity;input.setAttribute('aria-label','Amount of '+item.name+' to discard in '+item.unit);input.oninput=()=>{item.discardQuantity=Number(input.value);saveDraft();};label.append(input);row.append(label);}if(receipt.mode!=='waste'&&(item.needsReview||item.amountBasis==='full-pack'||item.amountBasis==='package')){const note=document.createElement('div');note.className='receipt-item-note';note.textContent=item.pending?'Lookup pending. Confirming now keeps this as an unknown package.':item.needsReview?(item.ingredient==='unmapped'?'Ingredient not mapped. Excluded from meal matching.':'Suggested ingredient: '+item.ingredient+'. Correct it to use in meal matching.'):item.amountBasis==='full-pack'?'Full pack assumed. Edit if partially used.':'Pack amount not known. Edit to match recipe quantities.';row.append(note);}const actions=document.createElement('div');actions.className='receipt-item-actions';const edit=document.createElement('button');edit.textContent='Correct';edit.setAttribute('aria-label','Correct '+item.name);edit.onclick=()=>editReceiptItem(item,receipt);if(receipt.mode!=='waste')actions.append(edit);if(!completed){const voidButton=document.createElement('button');voidButton.textContent='Void';voidButton.setAttribute('aria-label','Void '+item.name+' from final receipt');voidButton.onclick=()=>{receipt.items=receipt.items.filter(i=>i.id!==item.id);saveDraft();renderBasket();renderFinalReceipt(receipt,false);};actions.append(voidButton);}row.append(actions);$('finish-items').append(row);}const existing=lots.filter(l=>locationKey(l.location)===locationKey({area:receipt.area,shelf:receipt.shelf})).length;$('finish-explanation').textContent=completed?'Your confirmed receipt is saved with your kitchen profile.':receipt.mode==='waste'?`Remove these ${receipt.items.length} recorded items / chosen amounts from this source location and retain a waste receipt?`:receipt.mode==='shelf'?`Replace the ${existing} recorded items on this shelf with these ${receipt.items.length} scanned items?`:`Add these ${receipt.items.length} scanned items to the shelf’s existing stock?`;$('confirm-finish').hidden=completed;$('confirm-finish').disabled=!receipt.items.length;$('confirm-finish').textContent=receipt.mode==='waste'?'✓ Confirm removal receipt':receipt.mode==='shelf'?'✓ Confirm shelf receipt':'✓ Confirm grocery receipt';}
function editReceiptItem(item,receipt){$('finish-dialog').close();setView('checkout');$('checkout-complete').hidden=true;$('checkout-run').hidden=false;showProduct(products[item.barcode]||{name:item.name},item.barcode);editingId=item.id;for(const key of ['name','ingredient','quantity','unit','expires'])$(key).value=item[key]||'';$('add').hidden=false;$('skip-item').hidden=false;msg('Optional correction. Save it to return to the final receipt.');}
