function renderPlan(){renderUnlocks();const date=$('plan-date').value||today(),days=weekDates(date),plan=profile.plan||[];$('week-menu').replaceChildren();for(const day of days){const panel=document.createElement('section');panel.className='week-day'+(day===date?' selected':'');const heading=document.createElement('h4');heading.textContent=new Date(day+'T12:00:00').toLocaleDateString(undefined,{weekday:'short'});const d=document.createElement('small');d.textContent=new Date(day+'T12:00:00').toLocaleDateString(undefined,{day:'numeric',month:'short'});heading.append(d);panel.append(heading);const entries=plan.filter(p=>p.date===day);if(!entries.length){const empty=document.createElement('p');empty.textContent='A little room for inspiration.';panel.append(empty);}for(const entry of entries){const r=recipes.find(r=>r.id===entry.recipeId),meal=document.createElement('div'),name=document.createElement('strong'),detail=document.createElement('small'),remove=document.createElement('button');meal.className='planned-meal';name.textContent=r?.title||'Recipe no longer available';detail.textContent=entry.slot+' · '+entry.servings+' portions'+(entry.memberIds?.length?' · '+entry.memberIds.map(id=>(profile.members||[]).find(m=>m.id===id)?.name||'Member').join(', '):'')+(entry.adjustments?.length?' · '+entry.adjustments.join('; '):'');remove.className='outline';remove.textContent='Remove';remove.setAttribute('aria-label','Remove '+name.textContent+' from '+day);remove.onclick=()=>{profile.plan=plan.filter(p=>p.id!==entry.id);localStorage.setItem(PROFILE,JSON.stringify(profile));markDirty();renderPlan();};const log=document.createElement('button');log.textContent=entry.cookBatchId?'Serve / after meal':'Cook this meal';log.onclick=()=>{const batch=(profile.batches||[]).find(b=>b.id===entry.cookBatchId&&!b.undone);if(batch)journey.openServe(batch);else if(r)journey.openCook(r,entry);};meal.append(name,detail,log,remove);panel.append(meal);} $('week-menu').append(panel);}const selected=statisticsPeriod==='daily'?[date]:days;const summary=planSummary(plan,recipes,$('use-pantry').checked?lots:[],products,selected);$('stats-heading').textContent=statisticsPeriod==='daily'?'Daily totals · '+date:'Weekly totals · '+days[0]+' to '+days[6];$('plan-statistics').replaceChildren();const widget=(label,value,note='')=>{const box=document.createElement('div');box.className='stat-widget';const number=document.createElement('strong'),name=document.createElement('span'),caption=document.createElement('small');number.textContent=value;name.textContent=label;caption.textContent=note;box.append(number,name,caption);$('plan-statistics').append(box);};widget('Planned meals',summary.meals);widget('Planned portions',summary.portions);for(const [key,label,unit]of NUTRIENTS){const n=summary.totals[key];widget(label,n.known?Number(n.value.toPrecision(3))+' '+unit:'—',n.known<n.total?(n.known?'Partial · ':'No data · ')+n.known+'/'+n.total+' ingredient entries':'Estimate from mapped products');}for(const [id,list]of [['plan-ingredients',summary.requirements],['plan-shopping',summary.missing]]){$(id).replaceChildren();if(!list.length){const p=document.createElement('p');p.textContent=id==='plan-shopping'?(summary.meals?'No measured ingredient gaps. Check unmeasured ingredients below.':'Add a meal to see shopping gaps.'):'Add a menu to build your ingredient list.';$(id).append(p);}for(const ingredient of list){const row=document.createElement('div');row.className='ingredient-total';const name=document.createElement('span'),amount=document.createElement('strong');name.textContent=ingredient.ingredient;amount.textContent=displayAmount(ingredient.quantity,ingredient.unit,profile.units);row.append(name,amount);$(id).append(row);}}const unmeasured=[...new Set(plan.filter(p=>selected.includes(p.date)).flatMap(p=>(recipes.find(r=>r.id===p.recipeId)?.ingredients||[]).filter(i=>!i.optional&&(i.quantity==null||!i.unit)).map(i=>i.raw||i.ingredient)))];if(unmeasured.length){const title=document.createElement('h4');title.textContent='Unmeasured ingredients to review';$('plan-shopping').append(title);for(const item of unmeasured){const p=document.createElement('p');p.textContent=item;$('plan-shopping').append(p);}}$('plan-data-note').textContent=summary.unresolved?summary.unresolved+' ingredient quantities or recipe references remain unresolved. Shopping gaps and nutrition totals are incomplete.':'Totals cover the quantified ingredients in the selected menu. These are planning estimates; portions and actual consumption may differ.';}
$('plan-date').value=today();for(const id of ['menu-search','menu-location','menu-ready'])$(id).addEventListener(id==='menu-search'?'input':'change',findMeals);$('plan-date').onchange=()=>{renderPlan();findMeals();};$('plan-slot').onchange=findMeals;$('browse-menus').onclick=()=>setView('meals');for(const period of ['daily','weekly'])$('stats-'+period).onclick=()=>{statisticsPeriod=period;for(const p of ['daily','weekly'])$('stats-'+p).classList.toggle('selected',p===period);renderPlan();};
function persistProfile(){localStorage.setItem(PROFILE,JSON.stringify(profile));markDirty();}
function renderLocations(){const locations=[...(profile.locations||DEFAULT_LOCATIONS)];for(const lot of lots){if(lot.location&&!locations.some(l=>l.area===lot.location.area&&l.shelf===lot.location.shelf))locations.push({id:'from-'+lot.id,...lot.location});}$('location-list').replaceChildren();$('storage-area-list').replaceChildren();for(const area of [...new Set(locations.map(l=>l.area))]){const option=document.createElement('option');option.value=area;$('storage-area-list').append(option);}for(const location of locations){const card=document.createElement('article'),title=document.createElement('strong'),count=document.createElement('small'),edit=document.createElement('button');title.textContent=locationKey(location);count.textContent=lots.filter(l=>l.location?.area===location.area&&l.location?.shelf===location.shelf).length+' recorded items';edit.className='outline';edit.textContent='Edit location';edit.onclick=()=>{profile.locations=locations;editingLocationId=location.id;$('location-area').value=location.area;$('location-shelf').value=location.shelf;$('location-dialog').showModal();};card.append(title,count,edit);$('location-list').append(card);}const filter=$('shelf-filter'),old=filter.value;filter.replaceChildren();for(const area of ['',...new Set([...locations.map(l=>l.area),'Unassigned'])]){const option=document.createElement('option');option.value=area;option.textContent=area||'All storage';filter.append(option);}filter.value=old;}
$('manage-locations').onclick=()=>{editingLocationId=null;$('location-form').reset();$('location-dialog').showModal();};
$('location-form').onsubmit=e=>{e.preventDefault();const area=$('location-area').value.trim(),shelf=$('location-shelf').value.trim();if(!area||!shelf)return;profile.locations||=DEFAULT_LOCATIONS.map(l=>({...l}));const old=profile.locations.find(l=>l.id===editingLocationId);if(old){save(lots.map(l=>l.location?.area===old.area&&l.location?.shelf===old.shelf?{...l,location:{area,shelf}}:l));profile.locations=profile.locations.map(l=>l.id===old.id?{...l,area,shelf}:l);if(session?.area===old.area&&session?.shelf===old.shelf){session.area=area;session.shelf=shelf;saveDraft();}}else profile.locations.push({id:crypto.randomUUID(),area,shelf});persistProfile();$('location-dialog').close();pantry();findMeals();};
function renderHousehold(){$('household-members').replaceChildren();if(!(profile.members||[]).length){const empty=document.createElement('div');empty.className='empty-state';empty.textContent='Add people, their preferences and dietary advisors to personalise your menus.';$('household-members').append(empty);}for(const member of profile.members||[]){const card=document.createElement('article'),name=document.createElement('h3'),preferences=document.createElement('p'),metrics=document.createElement('p'),edit=document.createElement('button'),remove=document.createElement('button');name.textContent=member.name;preferences.textContent=member.advisors.map(a=>ADVISORS.find(x=>x[0]===a)?.[1]||a).join(' · ')+' · Avoid '+(member.avoid.join(', ')||'nothing entered');metrics.textContent='Portion factor '+member.portion+(member.age!=null?' · Age '+member.age:'')+(member.height!=null?' · '+member.height+' cm':'')+(member.weight!=null?' · '+member.weight+' kg':'');edit.textContent='Edit preferences';edit.onclick=()=>openMember(member);remove.className='outline';remove.textContent='Remove member';remove.onclick=()=>{profile.members=profile.members.filter(m=>m.id!==member.id);persistProfile();renderHousehold();findMeals();};card.append(name,preferences,metrics,edit,remove);$('household-members').append(card);}}
function openMember(member=null){editingMemberId=member?.id||null;$('member-form').reset();for(const key of ['name','age','height','weight','portion'])$('member-'+key).value=member?.[key]??(key==='portion'?1:'');$('member-avoid').value=member?.avoid.join(', ')||'';for(const [key,type]of [['allergies','allergy'],['intolerances','intolerance'],['religious','religious']])$('member-'+key).value=(member?.restrictions||[]).filter(r=>r.type===type).map(r=>r.term).join(', ');for(const input of document.querySelectorAll('[data-advisor]'))input.checked=(member?.advisors||['balanced']).includes(input.dataset.advisor);$('member-dialog').showModal();}
