$('add-member').onclick=()=>openMember();$('member-form').onsubmit=e=>{e.preventDefault();const member={id:editingMemberId||crypto.randomUUID(),name:$('member-name').value.trim(),portion:Number($('member-portion').value),avoid:$('member-avoid').value.split(',').map(x=>x.trim()).filter(Boolean),advisors:[...document.querySelectorAll('[data-advisor]:checked')].map(x=>x.dataset.advisor)};for(const key of ['age','height','weight'])member[key]=$('member-'+key).value?Number($('member-'+key).value):null;member.restrictions=[['allergies','allergy'],['intolerances','intolerance'],['religious','religious']].flatMap(([key,type])=>$('member-'+key).value.split(',').map(term=>term.trim()).filter(Boolean).map(term=>({type,term})));profile.members||=[];profile.members=profile.members.filter(m=>m.id!==member.id);profile.members.push(member);persistProfile();$('servings').value=householdPortions(profile.members);profile.servings=Number($('servings').value);persistProfile();$('member-dialog').close();renderHousehold();findMeals();};
