const dataUi=setupData({getData:()=>({profile,inventory:lots}),getUser:()=>user,isDemo:()=>demoMode,refreshSession,persist:persistProfile,download:fileDownload,addRecipe:record=>{if(!sharing.canWrite())throw Error('Open an editable kitchen before adding recipes.');const imported=recipeForReview(record);recipes=validateRecipes([...new Map([...recipes,imported].map(r=>[r.id,r])).values()]);localStorage.setItem(RECIPES,JSON.stringify(recipes));markDirty();findMeals();},applyNutrition:(lot,record,nutriments)=>{const p=products[lot.barcode]||{name:lot.name,quantity:lot.quantity+' '+lot.unit,product_quantity:lot.quantity,product_quantity_unit:lot.unit};products[lot.barcode]={...p,nutriments,nutritionProvenance:record.provenance};localStorage.setItem(PRODUCTS,JSON.stringify(products));markDirty();findMeals();}});
for(const option of $('country').options){if(option.value){const clone=option.cloneNode(true);$('source-country').append(clone);}}
const freshness=setupFreshness({getData:()=>({profile,inventory:lots}),save:next=>{save(next);pantry();findMeals();},persist:persistProfile,today,startWaste:(lot)=>{setView('checkout');setMode('waste');setArea(lot.location?.area||'Unassigned');$('shelf-name').value=lot.location?.shelf||'Unsorted';$('checkout-setup').hidden=false;$('checkout-complete').hidden=true;}});
await init();if(user&&!dirty&&!localStorage.getItem(KEY+'-shared-session'))try{await loadCloud(false);}catch(e){$('sync-status').textContent=e.message;}
syncReady=true;await sharing.resume().catch(e=>syncStatus(e.message,'pending'));autoSync.schedule();
resolveStartup();
if(user)openWorkspace();if(recoveryMode||inviteToken)$('account-dialog').showModal();

await access.checkConsent();

if(new URLSearchParams(location.search).get('import')==='starter'){try{const pending=JSON.parse(sessionStorage.getItem('offmenu-starter-import')||'null');if(pending){if(!sharing.canWrite())throw Error('Open an editable kitchen before importing this starter.');if(!/^[A-Z]{2}$/.test(pending.country)||!Array.isArray(pending.foods)||pending.foods.length>100||pending.foods.some(x=>typeof x!=='string'||x.length>200))throw Error('Invalid country starter');profile.shopping=profile.shopping||[];for(const name of pending.foods){const id='starter:'+pending.country+':'+normalize(name);if(!profile.shopping.some(x=>x.id===id))profile.shopping.push({id,name,amount:'Choose quantity · '+pending.country+' editorial starter',checked:false});}persistProfile();sessionStorage.removeItem('offmenu-starter-import');openWorkspace();setView('integrations');}}catch(e){syncStatus(e.message,'pending');}}

recipeLibrary=setupRecipeLibrary({today,inventory:()=>menuInventory(),download:fileDownload,saveRecipe:recipe=>{if(!sharing.canWrite())throw Error('Open an editable kitchen before saving a recipe.');recipes=validateRecipes([...new Map([...recipes,recipe].map(r=>[r.id,r])).values()]);localStorage.setItem(RECIPES,JSON.stringify(recipes));markDirty();findMeals();}});
